 editorKey=key;editorDirty=false;const r=project.request,fixed=r.mode==='retheme',editable=project.stage==='MECHANICS'&&r.mode==='create';const list=x=>Array.isArray(x)?x.join(', '):x||'';const brief=[...new Set([r.mechanicalBrief||'',r.mechanicalPreferences||''].map(x=>x.trim()).filter(Boolean))].join('\n\n');
 $('#project-editor').innerHTML=`<h2>${fixed?'Loaded script':'Script setup'}</h2><p class="engine-badge">${bootstrap.layaAvailable?'Embedded Laya · running locally':'Corpus rules'}</p><p class="muted">${editable?'Edit the brief, then apply it to rebuild unlocked roles.':fixed?(project.stage==='MECHANICS'?'The saved role list is loaded unchanged. Review the script, then confirm mechanics to choose identities.':'Your saved script is loaded. Choose identities or refine the optional character preferences.'):'Your role list is fixed. You can rename the project and refine its theme.'}</p><form id="workspace-form">${project.id==='draft'?'<label for="workspace-base">Start with</label><select id="workspace-base"><option value="">Design a new script</option><option value="tb">Trouble Brewing — unchanged</option><option value="bmr">Bad Moon Rising — unchanged</option><option value="snv">Sects &amp; Violets — unchanged</option></select>':''}<label for="project-name">Project name</label><input id="project-name" value="${esc(project.title)}">${editable?`<label for="workspace-brief">Mechanical brief</label><textarea id="workspace-brief" rows="5" ${editable?'':'readonly'}>${esc(brief)}</textarea>`:''}${!fixed?`<label for="workspace-tone">Tone</label><input id="workspace-tone" value="${esc(r.tone||'')}" placeholder="Paranoia, intrigue, chaotic wishes…">`:''}${editable?`<label for="workspace-complexity">Complexity</label><select id="workspace-complexity">${['low','medium','high'].map(x=>`<option ${r.complexity===x?'selected':''}>${x}</option>`).join('')}</select><label for="workspace-required">Required BOTC roles</label><input id="workspace-required" value="${esc(list(r.requiredBotcRoles))}" placeholder="Wizard, Alchemist…"><label for="workspace-excluded">Excluded BOTC roles</label><input id="workspace-excluded" value="${esc(list(r.excludedBotcRoles))}"><div class="counts">${Object.entries(teamNames).map(([t,name])=>`<div><label for="workspace-${t}">${name}</label><input id="workspace-${t}" type="number" min="0" max="60" value="${r.size?.[t]??project.entries.filter(e=>e.team===t).length}"></div>`).join('')}</div>`:''}${project.stage==='RETHEME'?`<label for="workspace-character-pool">Character pool</label><select id="workspace-character-pool"><option value="popular-racer" ${r.characterPool!=='all'?'selected':''}>Popular + Galactic Racer (${characterPool(kb.characters).length})</option><option value="all" ${r.characterPool==='all'?'selected':''}>Full catalogue (${kb.characters.length})</option></select><p class="muted">Required, essential and already selected identities are kept in the pool. Popularity uses the existing editorial recognisability ratings.</p><label for="workspace-theme">Theme / character direction</label><textarea id="workspace-theme" rows="3">${esc(r.theme||'')}</textarea><label for="workspace-priorities">Essential characters (priority)</label><textarea id="workspace-priorities" rows="3" placeholder="Yoda, Shade, Sebulba…">${esc(list(r.essentialCharacters))}</textarea><label for="workspace-avoid">Avoid characters / factions / eras</label><input id="workspace-avoid" value="${esc(list(r.avoid))}"><label class="check"><input id="workspace-sith" type="checkbox" ${r.demonsSith?'checked':''}>Demons must be Sith</label><details><summary>More character preferences</summary><label for="workspace-hard">Required characters before approval</label><input id="workspace-hard" value="${esc(list(r.requiredCharacters))}"><label for="workspace-factions">Preferred factions</label><input id="workspace-factions" value="${esc(list(r.factions))}"><label for="workspace-eras">Preferred eras</label><input id="workspace-eras" value="${esc(list(r.eras))}"><label for="workspace-racer">Galactic Racer emphasis</label><select id="workspace-racer">${['none','low','medium','high'].map(x=>`<option ${r.galacticRacerEmphasis===x?'selected':''}>${x}</option>`).join('')}</select><label for="workspace-min-racer">Minimum Racer characters</label><input id="workspace-min-racer" type="number" min="0" value="${Number(r.minRacer||0)}"><label class="check"><input id="workspace-scoundrels" type="checkbox" ${r.outsidersScoundrels?'checked':''}>Prefer scoundrels for Outsiders</label></details>`: ''}<p id="editor-state" class="muted">${fixed?'Script loaded.':'Requirements saved.'}</p><div class="actions">${project.id==='draft'?'': '<button type="submit">'+(fixed?(project.stage==='MECHANICS'?'Save name':'Save preferences'):'Save requirements')+'</button>'}${editable?'<button type="button" class="primary" id="workspace-rebuild">'+(project.id==='draft'?'Design script':'Apply & rebuild')+'</button>':''}</div></form>`;
 $('#workspace-form').oninput=()=>{editorDirty=true;$('#editor-state').textContent=fixed?'Unsaved changes. Save to apply them.':'Unsaved edits. Save requirements or apply & rebuild.';};
 const save=rebuild=>task(async()=>{const request={title:$('#project-name').value};if($('#workspace-tone'))request.tone=$('#workspace-tone').value;if(editable)Object.assign(request,{mechanicalBrief:$('#workspace-brief').value,theme:$('#workspace-brief').value,complexity:$('#workspace-complexity').value,requiredBotcRoles:$('#workspace-required').value,excludedBotcRoles:$('#workspace-excluded').value,mechanicalPreferences:'',size:Object.fromEntries(Object.keys(teamNames).map(t=>[t,Number($('#workspace-'+t).value)]))});if(project.stage==='RETHEME')Object.assign(request,{characterPool:$('#workspace-character-pool').value,theme:$('#workspace-theme').value,essentialCharacters:$('#workspace-priorities').value,avoid:$('#workspace-avoid').value,demonsSith:$('#workspace-sith').checked,requiredCharacters:$('#workspace-hard').value,factions:$('#workspace-factions').value,eras:$('#workspace-eras').value,galacticRacerEmphasis:$('#workspace-racer').value,minRacer:Number($('#workspace-min-racer').value),outsidersScoundrels:$('#workspace-scoundrels').checked});project=project.id==='draft'?await api('create',{request:{...project.request,...request}}):await api(rebuild?'redesign':'action',{id:project.id,version:project.version,...(rebuild?{request}:{action:{type:'request',request}})});editorDirty=false;editorKey=null;render();});
 if($('#workspace-base'))$('#workspace-base').onchange=e=>{if(e.target.value)return loadPublishedScript(e.target.value);};
 $('#workspace-form').onsubmit=e=>{e.preventDefault();save(false);};if($('#workspace-rebuild'))$('#workspace-rebuild').onclick=()=>save(true);
