 $('#script').innerHTML=`<div class="viewer-heading"><div><span class="eyebrow">FULL SCRIPT</span><h2>${esc(project.title)}</h2></div><label class="check"><input id="show-connections" type="checkbox" ${showConnections?'checked':''}>Show connections</label></div>${showConnections?'<p class="connection-legend"><span class="synergy">Curated synergy</span> · <span class="jinx">Official jinx</span> · <span class="tension">Tension</span> · <span class="signal">Shared signals</span></p><p class="muted">Click a role to highlight its links. Shared mechanic signals show overlap, not a proven synergy.</p>':''}<div class="script-groups">${Object.entries(teamNames).map(([t,name])=>`<section class="script-team" data-team="${t}"><h3>${name}<span>${project.entries.filter(e=>e.team===t).length}</span></h3>${project.entries.filter(e=>e.team===t).map(e=>{const link=showConnections?connected.get(e.botcRole.id):null;return `<button class="role script-card ${selected===e.botcRole.id?'selected':''} ${link?'connected '+link.type:''}" data-select="${e.botcRole.id}" aria-pressed="${selected===e.botcRole.id}"><div class="role-top"><strong>${esc(e.botcRole.name)}</strong>${link?`<span class="connection-label">${esc(link.type==='signal'?'shared signals':link.type)}</span>`:''}</div><small>${esc(e.botcRole.edition||'Custom')}</small><p class="script-ability">${esc(e.ability)}</p>${project.stage==='RETHEME'?`<div class="cast-line">${esc(e.starWarsIdentity?.name||'Choose an identity →')}</div>`:''}<div class="badges">${project.goals?.requiredRoles?.includes(e.botcRole.id)?'Requested · ':''}${e.locks.botcRole?'Role locked · ':''}${e.locks.starWarsCharacter?'Identity locked · ':''}${e.mechanical.concerns.length?'Review warnings':''}</div></button>`;}).join('')}</section>`).join('')}</div>${history}`;
 $('#show-connections').onchange=e=>{showConnections=e.target.checked;render();};$('#script').querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selectRole(b.dataset.select);});
 if(showConnections){const block=document.createElement('section');block.className='connection-list';block.innerHTML='<h3>Connections from this role</h3>'+ (links.length?links.map(l=>`<button class="connection-row ${l.type}" data-connection="${l.id}"><strong>${esc(l.name)}</strong><span>${esc(l.type==='signal'?'Shared signals: '+l.shared.join(', '):l.type)}</span>${l.rules.map(rule=>`<small>${esc(rule)}</small>`).join('')}</button>`).join(''):'<p class="muted">No direct links annotated for this script.</p>');$('#details').querySelector('h1')?.after(block);block.querySelectorAll('[data-connection]').forEach(b=>b.onclick=()=>{selectRole(b.dataset.connection);});}
