function rightPanel(){
 if(project.workflow!=='mechanics-first')return;
 const panel=$('#details'),isTheme=project.stage==='RETHEME';
 if(isTheme){
  const purpose=Array.from(panel.children).find(n=>n.tagName==='H3'&&n.textContent==='Mechanical purpose');
  if(purpose){const fold=document.createElement('details');fold.className='mechanical-fold';const summary=document.createElement('summary');summary.textContent='Mechanical purpose, synergies & jinxes';fold.append(summary);purpose.before(fold);let n=purpose;while(n&&n.tagName!=='H2'){const next=n.nextElementSibling;fold.append(n);n=next;}}
  const cards=Array.from(panel.querySelectorAll('details.card'));
  if(cards.length){const search=document.createElement('input');search.type='search';search.placeholder='Filter suggested identities';search.setAttribute('aria-label','Filter suggested identities');cards[0].before(search);const list=document.createElement('div');list.className='candidate-list';search.after(list);for(const card of cards)list.append(card);cards[0].open=true;search.oninput=()=>{for(const card of cards)card.hidden=!card.textContent.toLowerCase().includes(search.value.toLowerCase());};}
 }
 const notes=Array.from(panel.children).find(n=>n.tagName==='H3'&&n.textContent==='Review notes');
 if(notes){const fold=document.createElement('details');fold.className='notes-fold';const summary=document.createElement('summary');summary.textContent='Review notes & provenance';fold.append(summary);notes.before(fold);let node=notes;while(node){const next=node.nextElementSibling;fold.append(node);node=next;}}
 if($('#staged-replace'))$('#staged-replace').onclick=()=>task(async()=>{const list=await api('replacements',{id:project.id,roleId:selected});let slot=$('#inline-replacements');if(!slot){slot=document.createElement('div');slot.id='inline-replacements';$('#staged-replace').after(slot);}slot.innerHTML='<h3>Same-team alternatives</h3>'+list.slice(0,12).map(r=>`<details class="card"><summary>${esc(r.name)}</summary><p>${esc(r.explanation)}</p>${bullets(r.delta)}${bullets(r.warnings)}<button data-replace="${r.id}">Use ${esc(r.name)}</button></details>`).join('');slot.querySelectorAll('[data-replace]').forEach(b=>b.onclick=()=>action({type:'role',roleId:selected,newRoleId:b.dataset.replace},true));});
}

function selectRole(id){selected=id;render();const entry=project.entries.find(e=>e.botcRole.id===id);if(project.stage==='RETHEME'&&bootstrap.layaAvailable&&(!entry.layaCompared||entry.layaComparison?.method!=='grounded-five'||project.entries.some(e=>e!==entry&&e.starWarsIdentity?.id===entry.layaRecommendation?.choice)))task(async()=>{project=await api('laya-fit',{id:project.id,version:project.version,roleId:id});render();});}

