function startFresh(){project={id:'draft',version:0,title:'Untitled BOTC script',request:{mode:'create',title:'Untitled BOTC script',complexity:'medium',size:{townsfolk:13,outsider:4,minion:4,demon:4}},workflow:'mechanics-first',stage:'MECHANICS',state:'DRAFT',entries:[],history:[],archive:[],conversation:[],supplementalRoles:[],analysis:{}};selected=null;editorKey=null;editorDirty=false;$('#details').innerHTML='<h2>Build your mechanics</h2><p>Write your brief on the left and select Design script. Review the full script here before choosing identities.</p>';render();}
