function markdownImportDialog(){
 modal('Import Markdown',`<p>Choose a script exported by Clocktower Studio, or paste its complete Markdown including the import data block.</p><label for="markdown-file">Markdown file</label><input id="markdown-file" type="file" accept=".md,.markdown,text/markdown,text/plain"><p id="markdown-file-state" class="muted" role="status"></p><label for="markdown-text">Or paste exported Markdown</label><textarea id="markdown-text" rows="12" placeholder="Paste the complete exported Markdown here…"></textarea><button id="import-markdown-submit" class="primary">Import script</button>`);
 const input=$('#markdown-file'),text=$('#markdown-text'),state=$('#markdown-file-state'),submit=$('#import-markdown-submit');
 let reading=false;
 input.onchange=async()=>{
  const file=input.files[0];if(!file)return;
  reading=true;input.disabled=true;submit.disabled=true;text.value='';state.textContent='Reading '+file.name+'…';$('#modal-error').textContent='';
  try{text.value=await file.text();state.textContent='Loaded '+file.name+'. Select Import script to open it.';}
  catch{input.value='';state.textContent='File could not be read.';$('#modal-error').textContent='Windows could not read the selected file. If it is stored in OneDrive, download it first (Always keep on this device), then choose it again. You can also open the file in a text editor and paste its complete contents below.';}
  finally{reading=false;input.disabled=false;submit.disabled=false;}
 };
 submit.onclick=()=>{if(reading)return;return task(async()=>{
  if(!text.value.trim())throw Error('Choose a readable Markdown file or paste its contents first.');
  const imported=await api('import-md',{text:text.value});
  project=imported;selected=null;editorKey=null;editorDirty=false;render();close();
 });};
}
$('#import-md').onclick=markdownImportDialog;
